#!/usr/bin/env python3
"""Exact, reversible source guard. Baselines are pinned, not regenerated by tests."""
from pathlib import Path
import hashlib,json,re,zipfile
H=Path(__file__).resolve().parent; ROOT=H.parents[2]
M=json.loads((H/'manifest.json').read_text())
def digest(b):return hashlib.sha256(b).hexdigest()
def forward(raw,item):
 s=raw.decode()
 for e in item['edits']:
  assert e['before'] in s
  s=s.replace(e['before'],e['after'],1)
 return s.encode()
def check():
 mutations=0
 with zipfile.ZipFile(H/'baseline.zip') as z:
  for rel,item in M['files'].items():
   old=z.read(rel); now=(ROOT/rel).read_bytes(); expected=forward(old,item)
   assert digest(old)==item['before_sha256'],rel
   assert digest(now)==item['after_sha256'] and now==expected,rel
   # Record exact sequential spans, then invert in reverse order. Empty removals
   # and repeated identical constructor statements are unambiguous at those spans.
   replay=old.decode();spans=[]
   for edit in item['edits']:
    pos=replay.index(edit['before']);spans.append((pos,edit['before'],edit['after']))
    replay=replay[:pos]+edit['after']+replay[pos+len(edit['before']):]
   assert replay.encode()==now
   for pos,before,after in reversed(spans):
    assert replay[pos:pos+len(after)]==after
    replay=replay[:pos]+before+replay[pos+len(after):]
   assert replay.encode()==old,rel
   mutants=[now+b'\n',now.replace(b'isInRangeToRenderDist',b'isInRangeToRenderDistance',1)]
   if item['range_method']:
    mutants += [now.replace(b'64.0D *',b'63.0D *',1),now.replace(b'distance < range',b'distance <= range',1),now.replace(b'range *= 64.0D *',b'range = range * 64.0D *',1),now.replace(b'getEntityBoundingBox()',b'getBoundingBox()',1)]
   if item['variable_weight']:
    mutants += [now.replace(b'renderRangeWeight = 1.0D',b'renderRangeWeight = 10.0D',1),now.replace(b'renderRangeWeight = 10.0D',b'renderRangeWeight = 1.0D',1)]
   for mutant in mutants:
    if mutant!=now:
     assert digest(mutant)!=item['after_sha256'] and mutant!=expected
     mutations+=1
  for rel,expected in M['closure_sha256'].items():
   assert digest(z.read(rel))==expected and digest((ROOT/rel).read_bytes())==expected,rel
 # All sources remaining in this root (full checkout recommended) may not introduce the old access.
 assert not any(re.search(r'\b(?:this\.)?renderDistanceWeight\b',p.read_text()) for p in (ROOT/'src/main/java/com/hbm/entity').rglob('*.java'))
 print('PASS 11 exact forward/inverse complete files, 7 unchanged closure files, %d wrong-weight/selector/formula/unrelated-drift controls'%mutations)
 return mutations
if __name__=='__main__':check()
